// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address addr, uint256 depositAmount) public {
        vm.assume(depositAmount > 0);
        vm.assume(addr != address(0));
        vm.deal(addr, depositAmount);
        uint256 balanceBefore = address(c).balance;
        vm.prank(addr);
        c.deposit{value: depositAmount}();
        uint256 balanceAfterDep = address(c).balance;
        uint256 callerBalanceBefore = addr.balance;
        vm.prank(addr);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.withdrawAll.selector));
        uint256 callerBalanceAfter = addr.balance;
        uint256 balanceAfterWithdraw = address(c).balance;
        assertTrue(success && (balanceAfterWithdraw + (callerBalanceAfter - callerBalanceBefore) == balanceAfterDep - balanceBefore));
    }
}

